item.command:
/bin/bash -lc "timeout 30s python - <<'PY'
import urllib.request
for name in ['README.md','BUILD.md']:
 url='https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/doc/'+name
 try:
  data=urllib.request.urlopen(url,timeout=10).read().decode()
  print(url+'\\n'+data)
 except Exception as e: print(type(e).__name__,str(e))
PY"

